mapper.select:
SELECT COUNT(1)
FROM ai_message
WHERE session_id = #{sessionId}
  AND message_type = #{messageType}
  AND message_role = 'user'

SELECT MAX(message_seq)
FROM ai_message
WHERE session_id = #{sessionId}
  AND message_type = #{messageType}

SELECT DATE_FORMAT(create_time, '%Y-%m-%d') AS day, COUNT(1) AS count
FROM ai_message
WHERE create_time >= #{start}
  AND create_time < #{end}
GROUP BY DATE_FORMAT(create_time, '%Y-%m-%d')
ORDER BY day
